import{_ as a,o as t,c as i,ao as n}from"./chunks/framework.CYsVxDPg.js";const d=JSON.parse('{"title":"","description":"","frontmatter":{"layout":"home","hero":{"name":"QMagma.jl","text":"One-dimensional sill injection and crustal heating","tagline":"Compare discrete sill emplacement with an equivalent time-averaged magma source.","image":{"src":"/logo.svg","alt":"QMagma.jl"},"actions":[{"theme":"brand","text":"Installation","link":"/man/installation"},{"theme":"alt","text":"API reference 📚","link":"/man/listfunctions"},{"theme":"alt","text":"GitHub","link":"https://github.com/aelligp/QMagma.jl"}]},"features":[{"icon":"🎛️","title":"Interactive model","details":"Set model parameters and follow the thermal and eruption histories in a GLMakie window.","link":"/man/gui"},{"icon":"🌋","title":"Two emplacement models","details":"Run discrete sills, the Q_magma approximation, or both from the same initial state and mean accretion rate.","link":"/man/model"},{"icon":"💥","title":"Eruptions","details":"Choose a melt-thickness or pressure trigger independently from the vent-closure method.","link":"/man/eruptions"},{"icon":"⏳","title":"Tracers and zircon","details":"Record tracer temperature-time paths and calculate zircon crystallization ages with ZirconGrowth.jl.","link":"/man/tracers"}]},"headers":[],"relativePath":"index.md","filePath":"index.md","lastUpdated":null}'),r={name:"index.md"};function l(s,e,o,h,c,p){return t(),i("div",null,[...e[0]||(e[0]=[n(`<h2 id="Overview" tabindex="-1">Overview <a class="header-anchor" href="#Overview" aria-label="Permalink to &quot;Overview {#Overview}&quot;">​</a></h2><p>QMagma.jl solves the one-dimensional heat equation for a crustal column. It includes latent heat, temperature-dependent material properties, passive tracers, and optional eruptions. ZirconGrowth.jl converts tracer temperature-time paths into crystallization ages.</p><p>The two emplacement models are:</p><ul><li><p><strong>Discrete sills:</strong> finite-thickness sills are injected at random depths within the injection window. Each sill opens the host rock elastically.</p></li><li><p><strong>Q_magma:</strong> the same mean accretion rate is represented by a volumetric heat source and the ensemble-mean host-rock velocity of the discrete opening law, following <a href="https://www.nature.com/articles/ngeo2982" target="_blank" rel="noreferrer">Karlstrom et al. (2017)</a> and <a href="https://agupubs.onlinelibrary.wiley.com/doi/10.1029/2021JB021807" target="_blank" rel="noreferrer">Mittal et al. (2021)</a>.</p></li></ul><p>Use <code>Both (compare)</code> in the GUI to run the models from the same initial geotherm and mean accretion rate.</p><p>QMagma.jl builds on</p><ul><li><p><a href="https://github.com/JuliaGeodynamics/GeoParams.jl" target="_blank" rel="noreferrer">GeoParams.jl</a> - material physics (conductivity, heat capacity, density, melting parameterisations, latent heat)</p></li><li><p><a href="https://github.com/aelligp/ZirconGrowth.jl" target="_blank" rel="noreferrer">ZirconGrowth.jl</a> - zircon crystal growth along a cooling path</p></li><li><p><a href="https://github.com/MakieOrg/Makie.jl" target="_blank" rel="noreferrer">GLMakie.jl</a> - the interactive interface, loaded on demand through a package extension</p></li><li><p><a href="https://github.com/JuliaVTK/WriteVTK.jl" target="_blank" rel="noreferrer">WriteVTK.jl</a> and <a href="https://github.com/JuliaIO/JLD2.jl" target="_blank" rel="noreferrer">JLD2.jl</a> - output</p></li></ul><h2 id="Quick-start" tabindex="-1">Quick start <a class="header-anchor" href="#Quick-start" aria-label="Permalink to &quot;Quick start {#Quick-start}&quot;">​</a></h2><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">using</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> QMagma</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">using</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> GLMakie   </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># loads the GUI extension</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">sill_intrusion_1D</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">()</span></span></code></pre></div><p>See <a href="./man/gui">The GUI</a> for the controls and <a href="./man/scripting">Headless runs and export</a> for direct use of the solver functions.</p>`,10)])])}const u=a(r,[["render",l]]);export{d as __pageData,u as default};
